/* little paper-tag board that sits in the 3D world */
const wtag = (w, h, txt1, bg, col) => board(w, h, (x, cw, ch, t) => { x.fillStyle = bg || '#f3e7cc'; x.fillRect(0, 0, cw, ch); x.strokeStyle = 'rgba(0,0,0,0.3)'; x.lineWidth = 6; x.strokeRect(3, 3, cw - 6, ch - 6); ltxt(x, t || txt1, cw / 2, ch / 2, ch * 0.5, col || INK, 'center'); });
const sun = (S, col, inten, pos, tgt, size) => { const l = new THREE.DirectionalLight(col, inten); l.position.set(...pos); l.target.position.set(...(tgt || [0, 0, 0])); l.castShadow = true; l.shadow.mapSize.set(2048, 2048); const s = size || 10; Object.assign(l.shadow.camera, { left: -s, right: s, top: s, bottom: -s, near: 0.5, far: 60 }); l.shadow.bias = -0.0006; S.add(l); S.add(l.target); return l; };
function skyDome(S, top, bot, r) { const c = canvasTex(16, 256); const g = c.x.createLinearGradient(0, 0, 0, 256); g.addColorStop(0, top); g.addColorStop(0.55, bot); g.addColorStop(1, bot); c.x.fillStyle = g; c.x.fillRect(0, 0, 16, 256); c.t.needsUpdate = true;
  const m = new THREE.Mesh(new THREE.SphereGeometry(r || 80, 32, 16), new THREE.MeshBasicMaterial({ map: c.t, side: THREE.BackSide, fog: false, depthWrite: false })); S.add(m); return m; }

